00096 class ScanGenerator
00097 {
00098 private:
00099   uint32_t m_line, m_column;
00100   const uint32_t m_blockWidth, m_blockHeight;
00101   const uint32_t m_stride;
00102   const CoeffScanType m_scanType;
00103 
00104 public:
00105   ScanGenerator(uint32_t blockWidth, uint32_t blockHeight, uint32_t stride, CoeffScanType scanType)
00106     : m_line(0), m_column(0), m_blockWidth(blockWidth), m_blockHeight(blockHeight), m_stride(stride), m_scanType(scanType)
00107   { }
00108 
00109   uint32_t GetCurrentX() const { return m_column; }
00110   uint32_t GetCurrentY() const { return m_line; }
00111 
00112   uint32_t GetNextIndex(uint32_t blockOffsetX, uint32_t blockOffsetY)
00113   {
00114     const uint32_t rtn = ((m_line + blockOffsetY) * m_stride) + m_column + blockOffsetX;
00115 
00116     //advance line and column to the next position
00117     switch (m_scanType)
00118     {
00119       //------------------------------------------------
00120 
00121       case SCAN_DIAG:
00122 
00123         if ((m_column == m_blockWidth - 1) || (m_line == 0)) //if we reach the end of a rank, go diagonally down to the next one
00124         {
00125           m_line += m_column + 1;
00126           m_column = 0;
00127 
00128           if (m_line >= m_blockHeight) //if that takes us outside the block, adjust so that we are back on the bottom row
00129           {
00130             m_column += m_line - (m_blockHeight - 1);
00131             m_line = m_blockHeight - 1;
00132           }
00133         }
00134         else
00135         {
00136           m_column++;
00137           m_line--;
00138         }
00139         break;
00140 
00141       case SCAN_TRAV_HOR:
00142         if (m_line % 2 == 0)
00143         {
00144           if (m_column == (m_blockWidth - 1))
00145           {
00146             m_line++;
00147             m_column = m_blockWidth - 1;
00148           }
00149           else
00150           {
00151             m_column++;
00152           }
00153         }
00154         else
00155         {
00156           if (m_column == 0)
00157           {
00158             m_line++;
00159             m_column = 0;
00160           }
00161           else
00162           {
00163             m_column--;
00164           }
00165         }
00166         break;
00167 
00168       case SCAN_TRAV_VER:
00169         if (m_column % 2 == 0)
00170         {
00171           if (m_line == (m_blockHeight - 1))
00172           {
00173             m_column++;
00174             m_line = m_blockHeight - 1;
00175           }
00176           else
00177           {
00178             m_line++;
00179           }
00180         }
00181         else
00182         {
00183           if (m_line == 0)
00184           {
00185             m_column++;
00186             m_line = 0;
00187           }
00188           else
00189           {
00190             m_line--;
00191           }
00192         }
00193         break;
00194       //------------------------------------------------
00195 
00196       default:
00197 
00198         THROW("ERROR: Unknown scan type \"" << m_scanType << "\"in ScanGenerator::GetNextIndex");
00199         break;
00200     }
00201 
00202     return rtn;
00203   }
00204 };
00205 const int8_t g_BcwLog2WeightBase = 3;
00206 const int8_t g_BcwWeightBase = (1 << g_BcwLog2WeightBase);
00207 const int8_t g_BcwWeights[BCW_NUM] = { -2, 3, 4, 5, 10 };
00208 const int8_t g_BcwSearchOrder[BCW_NUM] = { BCW_DEFAULT, BCW_DEFAULT - 2, BCW_DEFAULT + 2, BCW_DEFAULT - 1, BCW_DEFAULT + 1 };
00209 int8_t g_BcwCodingOrder[BCW_NUM];
00210 int8_t g_BcwParsingOrder[BCW_NUM];
00211 
00212 int8_t getBcwWeight(uint8_t bcwIdx, uint8_t uhRefFrmList)
00213 {
00214   // Weghts for the model: P0 + w * (P1 - P0) = (1-w) * P0 + w * P1
00215   // Retuning  1-w for P0 or w for P1
00216   return (uhRefFrmList == REF_PIC_LIST_0 ? g_BcwWeightBase - g_BcwWeights[bcwIdx] : g_BcwWeights[bcwIdx]);
00217 }
00218 
00219 void resetBcwCodingOrder(bool bRunDecoding, const CodingStructure &cs)
00220 {
00221   // Form parsing order: { BCW_DEFAULT, BCW_DEFAULT+1, BCW_DEFAULT-1, BCW_DEFAULT+2, BCW_DEFAULT-2, ... }
00222   g_BcwParsingOrder[0] = BCW_DEFAULT;
00223   for (int i = 1; i <= (BCW_NUM >> 1); ++i)
00224   {
00225     g_BcwParsingOrder[2 * i - 1] = BCW_DEFAULT + (int8_t)i;
00226     g_BcwParsingOrder[2 * i] = BCW_DEFAULT - (int8_t)i;
00227   }
00228 
00229   // Form encoding order
00230   if (!bRunDecoding)
00231   {
00232     for (int i = 0; i < BCW_NUM; ++i)
00233     {
00234       g_BcwCodingOrder[(uint32_t)g_BcwParsingOrder[i]] = i;
00235     }
00236   }
00237 }
00238 
00239 uint32_t deriveWeightIdxBits(uint8_t bcwIdx) // Note: align this with TEncSbac::codeBcwIdx and TDecSbac::parseBcwIdx
00240 {
00241   uint32_t numBits = 1;
00242   uint8_t  bcwCodingIdx = (uint8_t)g_BcwCodingOrder[bcwIdx];
00243 
00244   if (BCW_NUM > 2 && bcwCodingIdx != 0)
00245   {
00246     uint32_t prefixNumBits = BCW_NUM - 2;
00247     uint32_t step = 1;
00248     uint8_t  prefixSymbol = bcwCodingIdx;
00249 
00250     // Truncated unary code
00251     uint8_t idx = 1;
00252     for (int ui = 0; ui < prefixNumBits; ++ui)
00253     {
00254       if (prefixSymbol == idx)
00255       {
00256         ++numBits;
00257         break;
00258       }
00259       else
00260       {
00261         ++numBits;
00262         idx += step;
00263       }
00264     }
00265   }
00266   return numBits;
00267 }
