00281 // initialize ROM variables
00282 void initROM()
00283 {
00284   gp_sizeIdxInfo = new SizeIndexInfoLog2();
00285   gp_sizeIdxInfo->init(MAX_CU_SIZE);
00286 
00287 
00288   SizeIndexInfoLog2 sizeInfo;
00289   sizeInfo.init(MAX_CU_SIZE);
00290 
00291   // initialize scan orders
00292   for (uint32_t blockHeightIdx = 0; blockHeightIdx < sizeInfo.numAllHeights(); blockHeightIdx++)
00293   {
00294     for (uint32_t blockWidthIdx = 0; blockWidthIdx < sizeInfo.numAllWidths(); blockWidthIdx++)
00295     {
00296       const uint32_t blockWidth  = sizeInfo.sizeFrom(blockWidthIdx);
00297       const uint32_t blockHeight = sizeInfo.sizeFrom(blockHeightIdx);
00298       const uint32_t totalValues = blockWidth * blockHeight;
00299 
00300       //--------------------------------------------------------------------------------------------------
00301 
00302       //non-grouped scan orders
00303 
00304       for (uint32_t scanTypeIndex = 0; scanTypeIndex < SCAN_NUMBER_OF_TYPES; scanTypeIndex++)
00305       {
00306         const CoeffScanType scanType = CoeffScanType(scanTypeIndex);
00307         ScanElement *       scan     = nullptr;
00308 
00309         if (blockWidthIdx < sizeInfo.numWidths() && blockHeightIdx < sizeInfo.numHeights())
00310         {
00311           scan = new ScanElement[totalValues];
00312         }
00313 
00314         g_scanOrder[SCAN_UNGROUPED][scanType][blockWidthIdx][blockHeightIdx] = scan;
00315 
00316         if (scan == nullptr)
00317         {
00318           continue;
00319         }
00320 
00321         ScanGenerator fullBlockScan(blockWidth, blockHeight, blockWidth, scanType);
00322 
00323         for (uint32_t scanPosition = 0; scanPosition < totalValues; scanPosition++)
00324         {
00325           const int rasterPos = fullBlockScan.GetNextIndex( 0, 0 );
00326           const int posY      = rasterPos / blockWidth;
00327           const int posX      = rasterPos - ( posY * blockWidth );
00328 
00329           scan[scanPosition].idx = rasterPos;
00330           scan[scanPosition].x   = posX;
00331           scan[scanPosition].y   = posY;
00332         }
00333       }
00334 
00335       //--------------------------------------------------------------------------------------------------
00336 
00337       //grouped scan orders
00338       const uint32_t* log2Sbb        = g_log2SbbSize[floorLog2(blockWidth)][floorLog2(blockHeight)];
00339       const uint32_t  log2CGWidth    = log2Sbb[0];
00340       const uint32_t  log2CGHeight   = log2Sbb[1];
00341 
00342       const uint32_t  groupWidth     = 1 << log2CGWidth;
00343       const uint32_t  groupHeight    = 1 << log2CGHeight;
00344       const uint32_t  widthInGroups = std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, blockWidth) >> log2CGWidth;
00345       const uint32_t  heightInGroups = std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, blockHeight) >> log2CGHeight;
00346 
00347       const uint32_t  groupSize      = groupWidth    * groupHeight;
00348       const uint32_t  totalGroups    = widthInGroups * heightInGroups;
00349 
00350       for (uint32_t scanTypeIndex = 0; scanTypeIndex < SCAN_NUMBER_OF_TYPES; scanTypeIndex++)
00351       {
00352         const CoeffScanType scanType = CoeffScanType(scanTypeIndex);
00353 
00354         ScanElement *scan = new ScanElement[totalValues];
00355 
00356         g_scanOrder[SCAN_GROUPED_4x4][scanType][blockWidthIdx][blockHeightIdx] = scan;
00357 
00358         if ( blockWidth > JVET_C0024_ZERO_OUT_TH || blockHeight > JVET_C0024_ZERO_OUT_TH )
00359         {
00360           for (uint32_t i = 0; i < totalValues; i++)
00361           {
00362             scan[i].idx = totalValues - 1;
00363             scan[i].x   = blockWidth - 1;
00364             scan[i].y   = blockHeight - 1;
00365           }
00366         }
00367 
00368         ScanGenerator fullBlockScan(widthInGroups, heightInGroups, groupWidth, scanType);
00369 
00370         for (uint32_t groupIndex = 0; groupIndex < totalGroups; groupIndex++)
00371         {
00372           const uint32_t groupPositionY  = fullBlockScan.GetCurrentY();
00373           const uint32_t groupPositionX  = fullBlockScan.GetCurrentX();
00374           const uint32_t groupOffsetX    = groupPositionX * groupWidth;
00375           const uint32_t groupOffsetY    = groupPositionY * groupHeight;
00376           const uint32_t groupOffsetScan = groupIndex     * groupSize;
00377 
00378           ScanGenerator groupScan(groupWidth, groupHeight, blockWidth, scanType);
00379 
00380           for (uint32_t scanPosition = 0; scanPosition < groupSize; scanPosition++)
00381           {
00382             const int rasterPos = groupScan.GetNextIndex( groupOffsetX, groupOffsetY );
00383             const int posY      = rasterPos / blockWidth;
00384             const int posX      = rasterPos - ( posY * blockWidth );
00385 
00386             scan[groupOffsetScan + scanPosition].idx = rasterPos;
00387             scan[groupOffsetScan + scanPosition].x   = posX;
00388             scan[groupOffsetScan + scanPosition].y   = posY;
00389           }
00390 
00391           fullBlockScan.GetNextIndex(0, 0);
00392         }
00393       }
00394 
00395       //--------------------------------------------------------------------------------------------------
00396     }
00397   }
00398 
00399   // initialize CoefTopLeftDiagScan8x8 for LFNST
00400   for( uint32_t blockWidthIdx = 0; blockWidthIdx < sizeInfo.numAllWidths(); blockWidthIdx++ )
00401   {
00402     const uint32_t blockWidth = sizeInfo.sizeFrom( blockWidthIdx );
00403 
00404     const static uint8_t g_auiXYDiagScan8x8[ 64 ][ 2 ] =
00405     {
00406       { 0, 0 }, { 0, 1 }, { 1, 0 }, { 0, 2 }, { 1, 1 }, { 2, 0 }, { 0, 3 }, { 1, 2 },
00407       { 2, 1 }, { 3, 0 }, { 1, 3 }, { 2, 2 }, { 3, 1 }, { 2, 3 }, { 3, 2 }, { 3, 3 },
00408       { 0, 4 }, { 0, 5 }, { 1, 4 }, { 0, 6 }, { 1, 5 }, { 2, 4 }, { 0, 7 }, { 1, 6 },
00409       { 2, 5 }, { 3, 4 }, { 1, 7 }, { 2, 6 }, { 3, 5 }, { 2, 7 }, { 3, 6 }, { 3, 7 },
00410       { 4, 0 }, { 4, 1 }, { 5, 0 }, { 4, 2 }, { 5, 1 }, { 6, 0 }, { 4, 3 }, { 5, 2 },
00411       { 6, 1 }, { 7, 0 }, { 5, 3 }, { 6, 2 }, { 7, 1 }, { 6, 3 }, { 7, 2 }, { 7, 3 },
00412       { 4, 4 }, { 4, 5 }, { 5, 4 }, { 4, 6 }, { 5, 5 }, { 6, 4 }, { 4, 7 }, { 5, 6 },
00413       { 6, 5 }, { 7, 4 }, { 5, 7 }, { 6, 6 }, { 7, 5 }, { 6, 7 }, { 7, 6 }, { 7, 7 }
00414     };
00415     for( int i = 0; i < 64; i++ )
00416     {
00417       g_coefTopLeftDiagScan8x8[ blockWidthIdx ][ i ].idx = g_auiXYDiagScan8x8[ i ][ 0 ] + g_auiXYDiagScan8x8[ i ][ 1 ] * blockWidth;
00418       g_coefTopLeftDiagScan8x8[ blockWidthIdx ][ i ].x   = g_auiXYDiagScan8x8[ i ][ 0 ];
00419       g_coefTopLeftDiagScan8x8[ blockWidthIdx ][ i ].y   = g_auiXYDiagScan8x8[ i ][ 1 ];
00420     }
00421   }
00422 
00423   initGeoTemplate();
00424 
00425   ::memset(g_isReusedUniMVsFilled, 0, sizeof(g_isReusedUniMVsFilled));
00426 
00427   for (int qp = 0; qp < 57; qp++)
00428   {
00429     int qpRem = (qp + 12) % 6;
00430     int qpPer = (qp + 12) / 6;
00431     int quantiserScale = g_quantScales[0][qpRem];
00432     int quantiserRightShift = QUANT_SHIFT + qpPer;
00433     double threshQP = ((double)(1 << quantiserRightShift)) / quantiserScale;
00434     g_paletteQuant[qp] = (int)(threshQP*0.16 + 0.5);
00435   }
00436 }
