00438 void destroyROM()
00439 {
00440   unsigned numWidths = gp_sizeIdxInfo->numAllWidths();
00441   unsigned numHeights = gp_sizeIdxInfo->numAllHeights();
00442 
00443   for (uint32_t groupTypeIndex = 0; groupTypeIndex < SCAN_NUMBER_OF_GROUP_TYPES; groupTypeIndex++)
00444   {
00445     for (uint32_t scanOrderIndex = 0; scanOrderIndex < SCAN_NUMBER_OF_TYPES; scanOrderIndex++)
00446     {
00447       for (uint32_t blockWidthIdx = 0; blockWidthIdx <= numWidths; blockWidthIdx++)
00448       {
00449         for (uint32_t blockHeightIdx = 0; blockHeightIdx <= numHeights; blockHeightIdx++)
00450         {
00451           delete[] g_scanOrder[groupTypeIndex][scanOrderIndex][blockWidthIdx][blockHeightIdx];
00452           g_scanOrder[groupTypeIndex][scanOrderIndex][blockWidthIdx][blockHeightIdx] = nullptr;
00453         }
00454       }
00455     }
00456   }
00457 
00458   delete gp_sizeIdxInfo;
00459   gp_sizeIdxInfo = nullptr;
00460 
00461   for( int modeIdx = 0; modeIdx < GEO_NUM_PARTITION_MODE; modeIdx++ )
00462   {
00463     delete[] g_GeoParams[modeIdx];
00464     g_GeoParams[modeIdx] = nullptr;
00465   }
00466   delete[] g_GeoParams;
00467   for( int i = 0; i < GEO_NUM_PRESTORED_MASK; i++ )
00468   {
00469     delete[] g_globalGeoWeights   [i];
00470     delete[] g_globalGeoEncSADmask[i];
00471     g_globalGeoWeights   [i] = nullptr;
00472     g_globalGeoEncSADmask[i] = nullptr;
00473   }
00474 }
